//! `emit_field` — prints the HLSL field bodies generated by tracing the generic
//! `boyko_shaderdsl::field` body over the `Emit` backend (`feature = "emit"`).
//!
//! Pass 1: this PRINTS to stdout. It does NOT splice into
//! `crates/boyko_rhi_vulkan/shaders/sdf_field.hlsli` and does NOT recompile any
//! `.spv` — that is Pass 2 (which also adds the `precise` qualifier and re-DXC + the
//! RTX gate). The output here is the textual-equivalence artifact: eyeball the
//! generated `smin`/`smax`/`combine` against the frozen `sdf_field.hlsli:110-129`.
//!
//! Run: `cargo run -p boyko_shaderdsl --features emit --bin emit_field`

fn main() {
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_field());
    // The surface-normal leaf (`sdf_normal`) — the central-difference gradient of the
    // whole edit-list field, generated from the SAME single source (`boyko_shaderdsl::
    // normal::sdf_normal_body`). Spliced between the `// === GENERATED NORMAL
    // BEGIN/END ===` sentinels in `sdf_field.hlsli`.
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_normal());
    // The brick snorm decode SCALE leaf (`m2_decode` — the GPU-spliceable `n *
    // band_half`), generated from `boyko_shaderdsl::brick::snorm_scale`. The byte →
    // normalize step is the hardware `R8_SNORM` sampler (not shader code). Spliced
    // between the `// === GENERATED decode_snorm8 BEGIN/END ===` sentinels in
    // `sdf_gbuffer_composite.hlsl`.
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_decode_snorm8());
    // The M2 cubic-surface leaves (A3) — the PURE-EXPRESSION leaves of the JCGT cubic
    // solver: `m2_cubic_eval` (Horner) and `m2_jcgt_cubic_coeffs` (the trilinear →
    // cubic-coefficient fold). Generated from `boyko_shaderdsl::brick::{cubic_eval,
    // jcgt_cubic_coeffs}`. Spliced between the `// === GENERATED m2_cubic_eval
    // BEGIN/END ===` and `// === GENERATED m2_jcgt_cubic_coeffs BEGIN/END ===`
    // sentinels in `sdf_gbuffer_composite.hlsl`. The root-finders that CALL them
    // (`m2_marmitt_root` / `m2_regula_falsi`) stay hand-written (runtime control flow).
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_cubic_eval());
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_jcgt_cubic_coeffs());
    // The brick-exit empty-skip MARCHER leaf (Increment 1 — the first CONTROL-FLOW leaf):
    // the `[unroll]` slab loop with the data-dependent `continue` + the final progress-
    // clamp ternary, generated from `boyko_shaderdsl::brick::dist_to_brick_exit_body` over
    // the `Emit` value backend + the `EmitCf` control-flow backend. Spliced between the
    // `// === GENERATED dist_to_brick_exit BEGIN/END ===` sentinels in
    // `sdf_gbuffer_composite.hlsl`. The host `boyko_sdf_math::brick::dist_to_brick_exit`
    // stays HAND-WRITTEN (firewall option B — see the brick module doc).
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_dist_to_brick_exit());
    // The brick-cell pointer-grid lookup MARCHER leaf (Increment 3 — the second CONTROL-FLOW
    // leaf, the first with EARLY RETURNS + a `StructuredBuffer<uint>` load + an `out float3`
    // param + `uint` index math), generated from `boyko_shaderdsl::brick::brick_cell_class_body`
    // over the `Emit` value backend + the `EmitCf` control-flow backend. Spliced between the
    // `// === GENERATED brick_cell_class BEGIN/END ===` sentinels in
    // `sdf_gbuffer_composite.hlsl` (the DEFINITION only — the 3 call sites are untouched). The
    // host `host_brick_cell` (boyko_rhi_vulkan::compute) stays HAND-WRITTEN (firewall option B).
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_brick_cell_class());
    // The regula-falsi root-refinement MARCHER leaf (Increment 4a — the THIRD CONTROL-FLOW
    // leaf, the first with a genuine RUNTIME `[loop]` (an `OpLoop`): five loop-carried Phi
    // vars {lo,hi,f_lo,f_hi as suppressed-decl params + mid as a local}, an in-loop early
    // return forwarded to the function IIFE, and a `m2_cubic_eval(c, mid)` call site),
    // generated from `boyko_shaderdsl::brick::m2_regula_falsi_body` over the `Emit` value
    // backend + the `EmitCf` control-flow backend. Spliced between the `// === GENERATED
    // m2_regula_falsi BEGIN/END ===` sentinels in `sdf_gbuffer_composite.hlsl` (the
    // DEFINITION only — the 2 call sites in `m2_marmitt_root` are untouched). The host
    // `boyko_sdf_math::brick::regula_falsi` stays HAND-WRITTEN (firewall option B); the eval
    // oracle is a frozen GPU-shape reference (the GPU's `1.0e-30` denom guard differs from
    // the host's `f32::MIN_POSITIVE`).
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_m2_regula_falsi());
    // The soft-shadow penumbra MARCHER leaf (Increment 4b — the FOURTH CONTROL-FLOW leaf, the
    // first with a real `break` + a `field_distance` CALL site): the runtime `[loop]` penumbra
    // accumulation (`min(res, SHADOW_K*d/t)`) with the occluder-hit early return, the
    // `t > T_MAX` break (the `brk` producer), and the `clamp01` tail, generated from
    // `boyko_shaderdsl::shadow::sdf_soft_shadow_body` over the `Emit` + `EmitCf` backends.
    // Spliced between the `// === GENERATED sdf_soft_shadow BEGIN/END ===` sentinels INSIDE
    // `sdf_soft_shadow` (the loop+tail SPAN only — the `dot(n,L)` preamble stays hand-written,
    // framing b). The host shadow march stays ANALYTIC (C1) — only the GPU span is generated.
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_sdf_soft_shadow());
}
